import { ScrollViewStyleReset, useServerDocumentContext } from "expo-router/html";
import type { PropsWithChildren } from "react";

/**
 * The root HTML document for web (expo-router static export).
 *
 * Adds the PWA surface on top of the default shell:
 * - manifest + theme-color + iOS icons → installable "app"
 * - service-worker registration in production builds (dist/sw.js is
 *   generated by `scripts/prepare-pages.js` via workbox; dev servers
 *   never register it, so live-reload is unaffected)
 *
 * `headNodes`/`bodyNodes` from useServerDocumentContext are REQUIRED with a
 * custom root: they carry the CSS links/preloads and the deferred bundle
 * scripts (bodyNodes must stay after {children} — chunk execution order).
 */

// Injected verbatim into <head>; registers the precache service worker.
const SW_REGISTRATION = `
if ("serviceWorker" in navigator) {
  window.addEventListener("load", function () {
    navigator.serviceWorker.register("/sw.js").catch(function (err) {
      console.warn("sw registration failed", err);
    });
  });
}
`;

export default function Root({ children }: PropsWithChildren) {
  const { htmlAttributes, bodyAttributes, headNodes, bodyNodes } =
    useServerDocumentContext();

  return (
    <html lang="en" {...htmlAttributes}>
      <head>
        <meta charSet="utf-8" />
        <meta httpEquiv="X-UA-Compatible" content="IE=edge" />
        <meta name="viewport" content="width=device-width, initial-scale=1, shrink-to-fit=no" />
        <link rel="manifest" href="/manifest.webmanifest" />
        <meta name="theme-color" content="#1a6fc4" />
        <link rel="icon" href="/icons/icon-192.png" type="image/png" />
        <link rel="apple-touch-icon" href="/icons/icon-192.png" />
        <ScrollViewStyleReset />
        {headNodes}
        {process.env.NODE_ENV === "production" ? (
          <script dangerouslySetInnerHTML={{ __html: SW_REGISTRATION }} />
        ) : null}
      </head>
      <body {...bodyAttributes}>
        {children}
        {bodyNodes}
      </body>
    </html>
  );
}
